<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {Search,Building2,ArrowRight,ArrowLeft,RefreshCw,BadgeCheck,MapPin,Clock3,BookOpen,Users,Info} from 'lucide-vue-next'
import SocialLinks from '../commerce/SocialLinks.vue'
import {request} from './client'
const emit=defineEmits(['navigate','changed'])
const data=ref({institutes:[],requests:[]}),query=ref(''),loading=ref(true),busy=ref(''),error=ref(''),message=ref('')
const selected=ref(null),catalogue=ref(null),profileLoading=ref(false),profileError=ref(''),page=ref(0),heading=ref(null)
let viewVersion=0,returnFocus=null
const rows=computed(()=>data.value.institutes.filter(p=>`${p.display_name} ${p.username} ${p.curriculum||''}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const membership=p=>data.value.requests.find(r=>r.profile===p.name)
const cleanProfile=p=>Object.fromEntries(Object.entries(p||{}).map(([key,value])=>[key,typeof value==='string'&&/^(none|null|undefined)$/i.test(value.trim())?'':value]))
const countryName=value=>{try{return /^[A-Za-z]{2}$/.test(value||'')?new Intl.DisplayNames(['en'],{type:'region'}).of(value.toUpperCase()):value}catch{return value}}
const profile=computed(()=>{const p=cleanProfile(catalogue.value?.profile||selected.value);return {...p,country:countryName(p.country)}})
const details=computed(()=>[['Subjects & curriculum',profile.value.curriculum],['Grades / levels',profile.value.grades],['Teaching languages',profile.value.languages],['Qualifications',profile.value.qualifications]].filter(([,value])=>value))
const fee=c=>c.fee_mode==='Free'?'Free':new Intl.NumberFormat('en-LK',{style:'currency',currency:'LKR'}).format(Number(c.fee)||0)
async function load(){loading.value=true;error.value='';try{const result=await request('profiles','institute_join_options',{},'GET');data.value={...result,institutes:result.institutes.map(p=>{const item=cleanProfile(p);return {...item,country:countryName(item.country)}})}}catch(e){error.value=e.message}finally{loading.value=false}}
async function register(p){if(busy.value)return;busy.value=p.name;error.value='';message.value='';try{await request('profiles','request_institutes',{profiles:[p.name],purpose:'New application'});await load();message.value=`Registration sent to ${p.display_name}. Your own teaching workspace remains available while you wait.`;window.dispatchEvent(new Event('sisu-memberships'));emit('changed')}catch(e){error.value=e.message}finally{busy.value=''}}
async function open(p){if(busy.value)return;busy.value=p.name;error.value='';try{await request('campus_context','select',{institute:p.workspace});window.location.assign('/campus')}catch(e){error.value=e.message;busy.value=''}}
async function view(p,event){returnFocus=event?.currentTarget?.id;selected.value=p;catalogue.value=null;page.value=0;await nextTick();heading.value?.focus();await readProfile()}
async function readProfile(more=false){
 if(!selected.value)return
 const version=++viewVersion,id=selected.value.name,nextPage=more?page.value+1:0
 profileLoading.value=true;profileError.value=''
 try{const result=await request('catalog','institute_profile',{profile:id,page:nextPage},'GET');if(version!==viewVersion)return
 catalogue.value=more?{...result,classes:[...catalogue.value.classes,...result.classes],teachers:[...catalogue.value.teachers,...result.teachers]}:result;page.value=nextPage
 }catch(e){if(version===viewVersion)profileError.value=e.message}finally{if(version===viewVersion)profileLoading.value=false}
}
async function back(){viewVersion++;selected.value=null;catalogue.value=null;profileLoading.value=false;await nextTick();document.getElementById(returnFocus)?.focus()}
onMounted(()=>{load();window.addEventListener('sisu-membership-cancelled',load)})
onBeforeUnmount(()=>{viewVersion++;window.removeEventListener('sisu-membership-cancelled',load)})
</script>
<template>
<section class="teacher-institutes" :class="{'is-profile':selected}" aria-labelledby="teacher-institutes-title">
 <template v-if="!selected">
  <header class="join-header"><div><h1 id="teacher-institutes-title">Join institute</h1><p>Find your next teaching community. Explore an institute’s profile before you register.</p></div><button class="join-button secondary" @click="emit('navigate','subscription')">View my plan<ArrowRight :size="16" aria-hidden="true"/></button></header>
  <div class="join-note"><Info :size="19" aria-hidden="true"/><p>Keep your personal classes while teaching at an institute. Once accepted, its active plan covers your assigned teaching there. Your personal teaching uses your own trial or plan.</p></div>
  <div class="institute-search-row"><label class="join-search-label" for="join-institute-search">Find an institute<span class="institute-search-field"><Search :size="20" aria-hidden="true"/><input id="join-institute-search" v-model="query" type="search" placeholder="Search name, username or subject" autocomplete="off"/></span></label><button class="join-button secondary" :disabled="loading||!!busy" @click="load"><RefreshCw :size="16" aria-hidden="true"/>Refresh</button></div>
 </template>
 <template v-else>
  <button class="join-back" @click="back"><ArrowLeft :size="18" aria-hidden="true"/>Back to institutes</button>
  <img v-if="profile.cover_image" class="profile-cover" :src="profile.cover_image" alt="" @error="$event.target.hidden=true"/>
  <header class="profile-header"><div class="institute-avatar large"><img v-if="profile.profile_image" :src="profile.profile_image" alt="" @error="$event.target.hidden=true"/><Building2 v-else :size="32" aria-hidden="true"/></div><div class="profile-heading"><div class="profile-title-row"><h1 id="teacher-institutes-title" ref="heading" tabindex="-1">{{profile.display_name}}</h1><span class="verified-label"><BadgeCheck :size="15" aria-hidden="true"/>Verified institute</span></div><div class="profile-meta"><span>@{{profile.username}}</span><span v-if="profile.lms_id||profile.code">{{profile.lms_id||profile.code}}</span><span v-if="profile.country"><MapPin :size="14" aria-hidden="true"/>{{profile.country}}</span></div><p v-if="profile.tagline" class="profile-tagline">{{profile.tagline}}</p></div></header>
 </template>
 <p v-if="error" class="join-error" role="alert">{{error}}</p><p v-if="message" class="institute-feedback" role="status">{{message}}</p>
 <template v-if="!selected">
  <div class="results-heading"><h2>Explore institutes</h2><span role="status">{{loading?'Loading…':`${rows.length} ${rows.length===1?'institute':'institutes'}`}}</span></div>
  <ul v-if="!loading" class="institute-results"><li v-for="p in rows" :key="p.name">
   <div class="institute-avatar"><img v-if="p.profile_image" :src="p.profile_image" alt="" loading="lazy" @error="$event.target.hidden=true"/><Building2 v-else :size="26" aria-hidden="true"/></div>
   <div class="institute-identity"><h3>{{p.display_name}}<BadgeCheck :size="17" class="verified-icon" aria-label="Verified institute"/></h3><span>@{{p.username}}</span><p v-if="p.tagline" class="institute-tagline">{{p.tagline}}</p><div v-if="p.country||p.curriculum" class="institute-meta"><span v-if="p.country"><MapPin :size="14" aria-hidden="true"/>{{p.country}}</span><span v-if="p.curriculum"><BookOpen :size="14" aria-hidden="true"/>{{p.curriculum}}</span></div><small v-if="membership(p)?.status==='Rejected'">Your previous request was declined. You can send a new request.</small></div>
   <div class="institute-actions"><button class="join-button secondary" :id="`institute-profile-${p.name}`" :aria-label="`View profile of ${p.display_name}`" @click="view(p,$event)">View profile<ArrowRight :size="16" aria-hidden="true"/></button><button v-if="membership(p)?.status==='Active'" class="join-button primary" :disabled="!!busy" @click="open(p)">Open workspace</button><span v-else-if="membership(p)?.status==='Pending'" class="membership-status pending"><Clock3 :size="16" aria-hidden="true"/>Pending approval</span><button v-else class="join-button primary" :disabled="!!busy" @click="register(p)">{{busy===p.name?'Sending…':'Request to join institute'}}</button></div>
  </li></ul>
  <div v-if="!loading&&!rows.length" class="institute-empty"><Search :size="28" aria-hidden="true"/><h3>{{query?'No matching institutes':'No institutes available yet'}}</h3><p>{{query?'Try a different name, username or subject.':'You can continue teaching in your personal workspace.'}}</p><button v-if="query" class="join-button secondary" @click="query=''">Clear search</button></div>
 </template>
 <template v-else>
  <div class="profile-layout"><div class="profile-content"><div class="profile-about"><h2>About the institute</h2><p v-if="profile.bio" class="profile-bio">{{profile.bio}}</p><p v-else class="muted">{{profileLoading?'Loading profile details…':'This institute has not added an introduction yet.'}}</p><dl v-if="details.length"><template v-for="[label,value] in details" :key="label"><dt>{{label}}</dt><dd>{{value}}</dd></template></dl><SocialLinks v-if="catalogue" :profile="profile"/></div>

  <div v-if="profileError" class="join-error" role="alert"><p>{{profileError}}</p><button class="join-button secondary" @click="readProfile(!!catalogue)">Retry loading profile</button></div>
  <template v-if="catalogue">
   <section class="profile-section"><h2><BookOpen :size="20" aria-hidden="true"/>Published classes <span>{{catalogue.class_count}}</span></h2><div v-if="catalogue.classes.length" class="public-grid"><article v-for="c in catalogue.classes" :key="c.name" class="public-item"><h3>{{c.title}}</h3><p>{{[c.subject,c.grade,c.teaching_medium].filter(Boolean).join(' · ')}}</p><p v-if="c.teacher_name">{{c.teacher_name}}</p><p v-if="c.schedule_label"><Clock3 :size="14" aria-hidden="true"/>{{c.schedule_label}}</p><strong>{{fee(c)}}</strong></article></div><p v-else class="muted">No public classes have been published yet.</p></section>
   <section class="profile-section"><h2><Users :size="20" aria-hidden="true"/>Teaching team <span>{{catalogue.teacher_count}}</span></h2><div v-if="catalogue.teachers.length" class="public-grid"><article v-for="teacher in catalogue.teachers" :key="teacher.name" class="public-item"><h3>{{teacher.display_name}}</h3><p>@{{teacher.username}}</p><p v-if="teacher.tagline">{{teacher.tagline}}</p><p v-if="teacher.curriculum">{{teacher.curriculum}}</p><p v-if="teacher.qualifications">{{teacher.qualifications}}</p><SocialLinks :profile="teacher"/></article></div><p v-else class="muted">No verified teachers are listed publicly yet.</p></section>
   <button v-if="catalogue.has_more" class="join-button secondary" :disabled="profileLoading" @click="readProfile(true)">{{profileLoading?'Loading…':'Show more classes and teachers'}}</button>
  </template>
  <p v-if="profileLoading" class="muted" role="status">Loading institute profile…</p>
  </div>
   <aside class="membership-panel"><h2>Teach with this institute</h2><template v-if="membership(selected)?.status==='Pending'"><span class="membership-status pending"><Clock3 :size="16" aria-hidden="true"/>Pending approval</span><p>Your request is with the institute. Its workspace becomes available after approval.</p></template><template v-else-if="membership(selected)?.status==='Active'"><span class="membership-status accepted"><BadgeCheck :size="16" aria-hidden="true"/>Membership approved</span><p>You can switch to this institute’s workspace.</p><button class="join-button primary" :disabled="!!busy" @click="open(selected)">Open workspace<ArrowRight :size="16" aria-hidden="true"/></button></template><template v-else><p>Send a registration request for the institute’s admin to review.</p><button class="join-button primary" :disabled="!!busy||!catalogue" @click="register(selected)">{{busy===selected.name?'Sending…':'Request to join institute'}}<ArrowRight :size="16" aria-hidden="true"/></button></template><p class="membership-help">Your personal workspace stays separate. The institute’s active plan covers your assigned teaching after approval.</p></aside>
  </div>
 </template>
</section>
</template>
<style scoped>
.teacher-institutes{margin:0 0 32px;padding:30px;background:var(--student-card,#fff);border:1px solid var(--student-border,#e6dff0);border-radius:16px;color:var(--student-text,#30243d);--join-purple:#592b91;--join-muted:#6b5a79}
