.results-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;padding-bottom:14px}.results-heading>span{font-size:13px;color:var(--join-muted)}.institute-results{list-style:none;padding:0;margin:0}.institute-results li{display:flex;align-items:center;gap:18px;padding:24px 0;border-top:1px solid var(--student-border,#e6dff0)}.institute-avatar{display:grid;place-items:center;position:relative;width:56px;height:56px;flex:none;border-radius:14px;background:#f3edf9;color:#674293;overflow:hidden}.institute-avatar img{width:100%;height:100%;object-fit:cover}.institute-identity{flex:1;min-width:0;overflow-wrap:anywhere}.institute-identity h3{display:flex;align-items:center;gap:8px}.verified-icon{flex:none;color:#217448}.institute-identity>span,.institute-identity small{font-size:13px;color:var(--join-muted);display:block;line-height:1.7}.institute-tagline{font-size:14px;margin:6px 0;color:#51455e;line-height:1.6}.institute-meta{display:flex;flex-wrap:wrap;gap:6px 16px;margin-top:8px;font-size:12px;color:var(--join-muted)}.institute-meta span{display:flex;gap:5px;align-items:center}.institute-meta svg{flex:none}.institute-actions{display:flex;align-items:center;gap:10px;flex-shrink:0}.membership-status{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:9px 12px;border-radius:8px;font-size:12px;font-weight:600;line-height:1.5}.pending{color:#79500b;background:#fff3dc}.accepted{color:#216342;background:#eaf5ef}.institute-empty{display:flex;flex-direction:column;align-items:center;text-align:center;padding:36px 16px;color:var(--join-muted);border-top:1px solid #e6dff0}.institute-empty h3{margin-top:16px}.institute-empty p{font-size:14px;line-height:1.6}.institute-feedback,.join-error{padding:14px 18px;border-radius:10px;line-height:1.6;font-size:14px}.institute-feedback{color:#246143;background:#edf7f0}.join-error{color:#963440;background:#fff0f2}
